INSERT INTO public_reports (report_reference, reporter_name, reporter_email, reporter_phone, report_type, report_category, subject, description, department_id, status, priority, assigned_to, submitted_at) VALUES
('PBLC-2022-0001', 'Jane Citizen', 'jane.citizen@email.com', '+27 82 123 4567', 'complaint', 'procurement_process', 'Concerns about school construction tender', 'I have observed that the specifications for the school construction tender in Orange Farm appear to favor certain suppliers. The requirements for CIDB 3GB seem excessive for a primary school project.', (SELECT id FROM departments WHERE code = 'DBE'), 'resolved', 'low', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2022-03-15'),
('PBLC-2022-0002', 'Thabo Moi', 'thabo.moi@email.com', '+27 83 456 7890', 'complaint', 'contract_award', 'Question regarding highway contract award', 'I would like to understand why the highway rehabilitation contract was awarded to a company not based in the affected province when there are qualified local contractors.', (SELECT id FROM departments WHERE code = 'DOT'), 'resolved', 'low', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2022-06-20'),
('PBLC-2023-0003', 'Anonymous Supplier', 'anon@supplier.co.za', '+27 84 567 8901', 'complaint', 'procurement_process', 'Tender document accessibility issues', 'The tender documents for the medical equipment tender are not accessible to smaller suppliers who cannot afford the registration fees for the portal.', (SELECT id FROM departments WHERE code = 'DOH'), 'resolved', 'medium', (SELECT id FROM users WHERE employee_id = 'EMP-002'), '2023-02-10'),
('PBLC-2023-0004', 'Community Organization', 'info@community.org.za', '+27 11 555 1234', 'inquiry', 'tender_clarity', 'Request for clarification on housing project', 'Our community organization would like clarification on the criteria for RDP allocation in the Orange Farm housing project. The communication has been unclear.', (SELECT id FROM departments WHERE code = 'DHS-HS'), 'resolved', 'low', (SELECT id FROM users WHERE employee_id = 'EMP-003'), '2023-05-15'),
('PBLC-2023-0005', 'Concerned Parent', 'parent@email.com', '+27 21 987 6543', 'complaint', 'project_quality', 'Quality concerns about new school building', 'The newly constructed primary school in my area has visible cracks in the walls and leaking roofs just months after completion.', (SELECT id FROM departments WHERE code = 'DBE'), 'investigating', 'high', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2023-09-01'),
('PBLC-2024-0006', 'Business Association', 'secretary@bus assoc.co.za', '+27 12 345 6789', 'feedback', 'procurement_process', 'Appreciation for transparent tender process', 'We appreciate the transparency improvements in recent tender processes. The public visibility of bid evaluations helps our members understand decisions.', (SELECT id FROM departments WHERE code = 'NT'), 'resolved', 'low', NULL, '2024-01-20'),
('PBLC-2024-0007', 'Local Contractor', 'local@contractor.co.za', '+27 31 555 4321', 'complaint', 'contract_award', 'Local subcontracting concerns', 'The large infrastructure projects are not fulfilling their local subcontracting requirements as stated in the tender documents.', (SELECT id FROM departments WHERE code = 'DOT'), 'under_review', 'medium', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2024-03-10'),
('PBLC-2024-0008', 'NGO Representative', 'ngo@water.org.za', '+27 21 444 3333', 'inquiry', 'tender_clarity', 'Environmental impact query for desalination', 'We need information on the environmental impact assessment for the Cape Town desalination project tender.', (SELECT id FROM departments WHERE code = 'DWS'), 'resolved', 'low', (SELECT id FROM users WHERE employee_id = 'EMP-003'), '2024-04-05'),
('PBLC-2024-0009', 'Hospital Staff Representative', 'staff@hospital.co.za', '+27 43 222 1111', 'complaint', 'project_quality', 'Equipment maintenance delays', 'The maintenance contract for our hospital equipment has resulted in significant delays in repairs, affecting patient care.', (SELECT id FROM departments WHERE code = 'DOH'), 'investigating', 'high', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2024-08-15'),
('PBLC-2025-0010', 'Municipal Liaison', 'liaison@city.co.za', '+27 15 888 7777', 'suggestion', 'procurement_process', 'Suggestion for tender notifications', 'It would be helpful if tender notifications could be sent via SMS to registered suppliers in addition to email.', (SELECT id FROM departments WHERE code = 'NT'), 'resolved', 'low', NULL, '2025-01-05'),
('PBLC-2025-0011', 'Contractor Association', 'info@sacontractors.co.za', '+27 11 999 8888', 'feedback', 'procurement_process', 'Feedback on tender evaluation criteria', 'The new evaluation criteria framework is clearer but we suggest weights be published earlier in the process.', (SELECT id FROM departments WHERE code = 'NT'), 'resolved', 'medium', NULL, '2025-02-28'),
('PBLC-2025-0012', 'Resident', 'resident@email.com', '+27 12 777 6666', 'complaint', 'project_quality', 'Road works quality issues', 'The recently completed road maintenance on the N3 has deteriorated significantly within months, raising quality concerns.', (SELECT id FROM departments WHERE code = 'DOT'), 'under_review', 'high', (SELECT id FROM users WHERE employee_id = 'EMP-004'), '2025-03-15'),
('PBLC-2025-0013', 'Educational NGO', 'edu@ngo.co.za', '+27 21 666 5555', 'inquiry', 'tender_clarity', 'Textbook tender requirements', 'We need clarification on the B-BBEE requirements for the textbook supply tender as they seem to exclude many smaller publishers.', (SELECT id FROM departments WHERE code = 'DBE'), 'resolved', 'low', (SELECT id FROM users WHERE employee_id = 'EMP-002'), '2025-04-10');
INSERT INTO whistleblower_reports (report_reference, access_code, report_category, report_subject, incident_description, incident_date, incident_location, tender_reference, contract_reference, department, amount_involved, officials_involved, suppliers_mentioned, evidence_description, status, priority, protection_requested, submitted_at, investigation_status) VALUES
('WB-2022-0001', 'ACC-1A2B-3C4D-5E6F', 'bid_rigging', 'Suspicious bid coordination in hospital tender', 'Multiple suppliers submitted identical technical proposals with only price differences of less than 2% for the hospital bed tender. All proposals came from suppliers who attended the same pre-bid meeting.', '2022-04-15', 'Gauteng Province', 'NT/2022/00078', NULL, 'Health', 75000000.00, '{"Hospital Procurement Manager"}', '{"MedSupply SA", "Phakama Construction"}', 'Email correspondence obtained showing coordination', 'resolved', 'medium', true, '2022-05-20', 'Investigated and resolved - insufficient evidence'),
('WB-2022-0002', 'ACC-7X8Y-9Z0A-1B2C', 'corruption', 'Procurement officer demands payment', 'A procurement officer demanded 10% of contract value as facilitation fee for ensuring our bid was evaluated favorably in the road construction tender.', '2022-06-20', 'KwaZulu-Natal', 'DOT/2021/00012', NULL, 'Transport', 500000.00, '{"Deputy Director Procurement"}', '{}', 'Recorded conversation available', 'resolved', 'high', true, '2022-07-10', 'Criminal investigation - officer dismissed'),
('WB-2023-0003', 'ACC-3D4E-5F6G-7H8I', 'price_fixing', 'Cartel behavior in construction materials', 'Major construction suppliers appear to have agreed not to bid against each other, dividing the market by province. When we tried to bid outside our province, we received threats.', '2023-01-15', 'National', NULL, 'C-2022-0009', 'Human Settlements', 150000000.00, '{"Industry association members"}', '{"BuildIt Construction", "Phakama Construction", "KZN Civil"}', 'Meeting minutes and WhatsApp messages', 'investigating', 'critical', true, '2023-02-28', 'Competition Commission investigation ongoing'),
('WB-2023-0004', 'ACC-9J0K-1L2M-3N4O', 'tender_manipulation', 'Tender specifications tailored for single supplier', 'The smart city tender specifications were written in such a way that only one supplier could meet all requirements. The specific API calls and integration requirements match exactly what one vendor proposed during preliminary discussions.', '2023-03-01', 'Gauteng', 'COT/2022/00056', NULL, 'Tshwane Metro', 265000000.00, '{"IT Manager", "Project Coordinator"}', '{"TechSavvy Solutions"}', 'Emails showing draft specifications shared before official publication', 'under_review', 'high', false, '2023-04-15', 'Under preliminary review'),
('WB-2023-0005', 'ACC-5P6Q-7R8S-9T0U', 'conflict_of_interest', 'Family member awarded major contract', 'A senior official awarded a major infrastructure contract to a company owned by his brother-in-law. The company was registered just weeks before the tender and had no previous government experience.', '2023-06-01', 'Eastern Cape', NULL, 'C-2023-0016', 'Public Works', 120000000.00, '{"Chief Director"}', '{"Nxa Construction"}', 'Company registration documents and family relationship evidence', 'investigating', 'critical', true, '2023-07-01', 'Full investigation launched'),
('WB-2024-0006', 'ACC-1V2W-3X4Y-5Z6A', 'misappropriation', 'Variation orders inflate contract value', 'The solar farm project has been issuing variation orders that significantly exceed original contract requirements, effectively awarding additional work without competitive bidding.', '2024-02-15', 'Northern Cape', 'DMR/2023/00144', 'C-2023-0014', 'Energy', 85000000.00, '{"Project Director", "Financial Manager"}', '{"Green Energy Solutions"}', 'Variation order documentation and financial records', 'under_review', 'high', true, '2024-03-01', 'Preliminary assessment completed'),
('WB-2024-0007', 'ACC-7B8C-9D0E-1F2G', 'bid_rigging', 'Bid rotation scheme detected', 'Suppliers appear to be taking turns winning tenders. Analysis of tenders over 3 years shows Supplier A wins year 1, Supplier B wins year 2, Supplier C wins year 3, then rotates back.', '2024-05-01', 'National', NULL, NULL, 'Multiple departments', 500000000.00, '{"Senior Procurement Officials"}', '{"Multiple construction firms"}', 'Tender award pattern analysis', 'investigating', 'critical', true, '2024-05-20', 'AI pattern detected - investigation ongoing'),
('WB-2024-0008', 'ACC-3H4I-5J6K-7L8M', 'fraud', 'Ghost companies receiving payments', 'Discovered that contracts are being awarded to companies that do not exist at the registered addresses and cannot be found at their stated premises, yet they receive payments.', '2024-08-10', 'Gauteng', NULL, NULL, 'Education', 45000000.00, '{"Procurement Clerk"}', '{"Fictitious Company 1", "Fictitious Company 2"}', 'Site verification reports', 'investigating', 'critical', true, '2024-08-20', 'SIU investigation initiated'),
('WB-2025-0009', 'ACC-9N0O-1P2Q-3R4S', 'tender_manipulation', 'Evaluation scores manipulated', 'A colleague observed and reported that evaluation scores for a major tender were changed after the evaluation meeting to favor a particular bidder.', '2025-01-20', 'Gauteng', 'NT/2025/00221', NULL, 'Treasury', 350000000.00, '{"Evaluation Committee Chair"}', '{"Preferred Vendor"}', 'Original and modified score sheets', 'under_review', 'high', true, '2025-02-05', 'Internal investigation'),
('WB-2025-0010', 'ACC-5T6U-7V8W-9X0Y', 'corruption', 'Kickbacks from medical supplies', 'Evidence of medical equipment purchases being inflated by 30-40% with the difference being paid back to hospital administrators.', '2025-03-15', 'Multiple provinces', 'DOH/2023/00122', NULL, 'Health', 15000000.00, '{"Hospital CEOs", "Procurement Managers"}', '{"Medical Supplier Network"}', 'Financial records and whistleblower testimony', 'investigating', 'critical', true, '2025-04-01', 'Multi-agency investigation');